<!DOCTYPE html>
<html lang="zh">
<head>
    <meta charset="UTF-8">
    <title>鹈鹕骑自行车</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            overflow: hidden;
            background-color: #87CEEB;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
        }
        #container {
            position: relative;
            width: 800px;
            height: 500px;
            overflow: hidden;
        }
        canvas {
            display: block;
            background-color: #87CEEB;
        }
    </style>
</head>
<body>
    <div id="container">
        <canvas id="scene" width="800" height="500"></canvas>
    </div>

    <script>
        const canvas = document.getElementById('scene');
        const ctx = canvas.getContext('2d');
        let animationId;
        let frame = 0;

        function drawPelican(x, y, legAngle) {
            // 身体
            ctx.fillStyle = 'white';
            ctx.beginPath();
            ctx.ellipse(x, y, 30, 25, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#333';
            ctx.stroke();

            // 脖子
            ctx.beginPath();
            ctx.moveTo(x, y - 10);
            ctx.lineTo(x, y - 40);
            ctx.lineWidth = 8;
            ctx.strokeStyle = 'white';
            ctx.stroke();

            // 头
            ctx.beginPath();
            ctx.arc(x, y - 40, 12, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            // 喙
            ctx.fillStyle = '#FFA500';
            ctx.beginPath();
            ctx.moveTo(x, y - 40);
            ctx.lineTo(x + 40, y - 40);
            ctx.lineTo(x + 30, y - 35);
            ctx.lineTo(x + 40, y - 30);
            ctx.lineTo(x, y - 30);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#CC8400';
            ctx.stroke();

            // 喉囊
            ctx.fillStyle = '#FFFF00';
            ctx.beginPath();
            ctx.moveTo(x + 15, y - 35);
            ctx.lineTo(x + 35, y - 35);
            ctx.lineTo(x + 30, y - 20);
            ctx.lineTo(x + 20, y - 20);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#CCCC00';
            ctx.stroke();

            // 眼睛
            ctx.fillStyle = 'black';
            ctx.beginPath();
            ctx.arc(x + 5, y - 42, 2, 0, Math.PI * 2);
            ctx.fill();

            // 翅膀（前伸扶车把）
            ctx.fillStyle = 'white';
            ctx.beginPath();
            ctx.moveTo(x - 15, y - 5);
            ctx.lineTo(x - 60, y - 25);
            ctx.lineTo(x - 40, y);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#333';
            ctx.stroke();
            // 黑色翅尖
            ctx.fillStyle = 'black';
            ctx.beginPath();
            ctx.moveTo(x - 60, y - 25);
            ctx.lineTo(x - 55, y - 20);
            ctx.lineTo(x - 40, y);
            ctx.lineTo(x - 45, y + 2);
            ctx.closePath();
            ctx.fill();

            // 另一只翅膀（自然状态）
            ctx.fillStyle = 'white';
            ctx.beginPath();
            ctx.moveTo(x + 15, y - 5);
            ctx.lineTo(x + 40, y + 10);
            ctx.lineTo(x + 20, y + 15);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();
            // 黑色翅尖
            ctx.fillStyle = 'black';
            ctx.beginPath();
            ctx.moveTo(x + 40, y + 10);
            ctx.lineTo(x + 35, y + 15);
            ctx.lineTo(x + 20, y + 15);
            ctx.lineTo(x + 25, y + 12);
            ctx.closePath();
            ctx.fill();

            // 脚（踩脚踏）
            const footRadius = 8;
            const leftFootX = x - 15 + Math.cos(legAngle) * 25;
            const leftFootY = y + 25 + Math.sin(legAngle) * 25;
            const rightFootX = x - 15 + Math.cos(legAngle + Math.PI) * 25;
            const rightFootY = y + 25 + Math.sin(legAngle + Math.PI) * 25;

            ctx.fillStyle = '#FFA500';
            // 腿
            ctx.beginPath();
            ctx.moveTo(x - 15, y + 20);
            ctx.lineTo(leftFootX, leftFootY);
            ctx.moveTo(x - 15, y + 20);
            ctx.lineTo(rightFootX, rightFootY);
            ctx.lineWidth = 4;
            ctx.strokeStyle = '#FFA500';
            ctx.stroke();
            // 脚
            ctx.beginPath();
            ctx.arc(leftFootX, leftFootY, footRadius, 0, Math.PI * 2);
            ctx.fill();
            ctx.beginPath();
            ctx.arc(rightFootX, rightFootY, footRadius, 0, Math.PI * 2);
            ctx.fill();
        }

        function drawBicycle(x, y, wheelRotation) {
            // 红色车架
            ctx.strokeStyle = '#FF0000';
            ctx.lineWidth = 6;
            // 主三角
            ctx.beginPath();
            ctx.moveTo(x, y);
            ctx.lineTo(x + 40, y - 40);
            ctx.lineTo(x + 80, y);
            ctx.lineTo(x, y);
            ctx.stroke();
            // 座管
            ctx.beginPath();
            ctx.moveTo(x + 20, y - 20);
            ctx.lineTo(x + 20, y - 60);
            ctx.stroke();
            // 立管
            ctx.beginPath();
            ctx.moveTo(x + 60, y - 20);
            ctx.lineTo(x + 60, y - 40);
            ctx.stroke();
            // 前叉
            ctx.beginPath();
            ctx.moveTo(x + 80, y);
            ctx.lineTo(x + 80, y - 30);
            ctx.stroke();

            // 车把
            ctx.beginPath();
            ctx.moveTo(x + 60, y - 40);
            ctx.lineTo(x + 80, y - 40);
            ctx.lineTo(x + 80, y - 50);
            ctx.stroke();
            // 车把横杆
            ctx.beginPath();
            ctx.moveTo(x + 75, y - 50);
            ctx.lineTo(x + 85, y - 50);
            ctx.stroke();

            // 座垫
            ctx.fillStyle = '#333';
            ctx.beginPath();
            ctx.ellipse(x + 20, y - 65, 10, 5, 0, 0, Math.PI * 2);
            ctx.fill();

            // 脚踏轴
            ctx.beginPath();
            ctx.arc(x - 15, y + 25, 5, 0, Math.PI * 2);
            ctx.fillStyle = '#333';
            ctx.fill();

            // 车轮
            const wheelRadius = 30;
            // 后轮
            drawWheel(x, y, wheelRadius, wheelRotation);
            // 前轮
            drawWheel(x + 80, y, wheelRadius, wheelRotation);
        }

        function drawWheel(cx, cy, radius, rotation) {
            // 轮圈
            ctx.beginPath();
            ctx.arc(cx, cy, radius, 0, Math.PI * 2);
            ctx.strokeStyle = '#333';
            ctx.lineWidth = 3;
            ctx.stroke();
            // 辐条
            ctx.strokeStyle = '#666';
            ctx.lineWidth = 1;
            for (let i = 0; i < 8; i++) {
                const angle = rotation + (Math.PI / 4) * i;
                const x2 = cx + Math.cos(angle) * radius;
                const y2 = cy + Math.sin(angle) * radius;
                ctx.beginPath();
                ctx.moveTo(cx, cy);
                ctx.lineTo(x2, y2);
                ctx.stroke();
            }
            // 轮轴
            ctx.beginPath();
            ctx.arc(cx, cy, 4, 0, Math.PI * 2);
            ctx.fillStyle = '#333';
            ctx.fill();
        }

        function drawScene(offsetX) {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // 天空
            ctx.fillStyle = '#87CEEB';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // 太阳
            ctx.fillStyle = '#FFD700';
            ctx.beginPath();
            ctx.arc(700, 80, 30, 0, Math.PI * 2);
            ctx.fill();

            // 云朵
            ctx.fillStyle = 'white';
            ctx.beginPath();
            ctx.arc(200, 70, 20, 0, Math.PI * 2);
            ctx.arc(230, 65, 25, 0, Math.PI * 2);
            ctx.arc(260, 70, 20, 0, Math.PI * 2);
            ctx.fill();

            ctx.beginPath();
            ctx.arc(500, 100, 15, 0, Math.PI * 2);
            ctx.arc(530, 95, 20, 0, Math.PI * 2);
            ctx.arc(560, 100, 15, 0, Math.PI * 2);
            ctx.fill();

            // 大海
            ctx.fillStyle = '#1E90FF';
            ctx.fillRect(0, 250, canvas.width, 100);
            // 波浪线
            ctx.strokeStyle = '#4169E1';
            ctx.lineWidth = 2;
            for (let i = 0; i < 5; i++) {
                const y = 280 + i * 10;
                ctx.beginPath();
                for (let x = 0; x < canvas.width; x += 20) {
                    const waveX = x + offsetX * 0.5;
                    ctx.lineTo(waveX, y + Math.sin((waveX + i * 40) * 0.05) * 5);
                }
                ctx.stroke();
            }

            // 沙滩
            ctx.fillStyle = '#F4A460';
            ctx.fillRect(0, 350, canvas.width, 50);

            // 棕榈树
            function drawPalmTree(x, y) {
                // 树干
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(x, y, 10, 60);
                // 树叶
                ctx.fillStyle = '#228B22';
                for (let i = 0; i < 6; i++) {
                    const angle = (Math.PI * 2 / 6) * i;
                    ctx.beginPath();
                    ctx.moveTo(x + 5, y);
                    ctx.lineTo(x + 5 + Math.cos(angle) * 40, y + Math.sin(angle) * 40);
                    ctx.lineTo(x + 5 + Math.cos(angle + 0.3) * 35, y + Math.sin(angle + 0.3) * 35);
                    ctx.closePath();
                    ctx.fill();
                }
            }
            drawPalmTree(100, 300);
            drawPalmTree(300, 310);
            drawPalmTree(600, 305);

            // 灯塔
            ctx.fillStyle = '#C0C0C0';
            ctx.fillRect(650, 200, 20, 150);
            ctx.fillStyle = '#DC143C';
            ctx.beginPath();
            ctx.moveTo(640, 200);
            ctx.lineTo(680, 200);
            ctx.lineTo(660, 180);
            ctx.closePath();
            ctx.fill();
            ctx.fillStyle = '#FFD700';
            ctx.beginPath();
            ctx.arc(660, 210, 8, 0, Math.PI * 2);
            ctx.fill();

            // 公路
            ctx.fillStyle = '#708090';
            ctx.fillRect(0, 400, canvas.width, 60);
            // 道路虚线
            ctx.strokeStyle = '#FFFF00';
            ctx.lineWidth = 4;
            ctx.setLineDash([20, 30]);
            ctx.beginPath();
            ctx.moveTo(0, 430);
            ctx.lineTo(canvas.width, 430);
            ctx.stroke();
            ctx.setLineDash([]);

            // 自行车和鹈鹕（居中）
            const bikeX = 400;
            const bikeY = 370;
            const wheelRotation = frame * 0.1;
            const legAngle = Math.sin(frame * 0.2) * 0.5;

            drawBicycle(bikeX, bikeY, wheelRotation);
            drawPelican(bikeX + 20, bikeY - 40, legAngle);
        }

        function animate() {
            frame++;
            const offsetX = frame % canvas.width;
            drawScene(offsetX);
            animationId = requestAnimationFrame(animate);
        }

        animate();

        window.addEventListener('resize', () => {
            canvas.width = canvas.clientWidth;
            canvas.height = canvas.clientHeight;
        });
    </script>
</body>
</html>
